def evaluate(evidence: dict) -> bool:
    m = evidence.get('metrics', {})
    greens = {'green','#008000','#00b050','#26a69a','#1f9d6e'}
    reds = {'red','#ff0000','#e5483f','#ef5350'}
    return str(m.get('chart_up_color','')).lower() in greens and str(m.get('chart_down_color','')).lower() in reds and m.get('legend_states_color_mapping') is True
